class Tokenizer{static tokenize(b){if(!b)return[];b=b.toLowerCase().replace(/[^\w\s]/g,"");const d=b.split(/\s+/).filter(c=>0<c.length),f=[];for(let c=0;c<b.length-1;c++){const g=b.substring(c,c+2);/\s/.test(g)||f.push(g)}return d.concat(f)}}"undefined"!==typeof globalThis&&(globalThis.Tokenizer=Tokenizer);"undefined"!==typeof module&&module.exports&&(module.exports=Tokenizer);class VectorScorer{static calculateCosineSimilarity(b,d){let f=0;Object.keys(b).forEach(c=>{d[c]&&(f+=b[c]*d[c])});return f}}"undefined"!==typeof globalThis&&(globalThis.VectorScorer=VectorScorer);"undefined"!==typeof module&&module.exports&&(module.exports=VectorScorer);class CustomSearchEngine{constructor(){this.docs=[];this.idf={};this.vectors=[];this.isLoaded=!1}async loadIndex(b="search_index.json"){try{const d=await (await fetch(b)).json();this.docs=d.docs;this.idf=d.idf;this.vectors=d.vectors;return this.isLoaded=!0}catch(d){return console.error("\u274c \u30a4\u30f3\u30c7\u30c3\u30af\u30b9\u30ed\u30fc\u30c9\u5931\u6557:",d),!1}}tokenize(b){return Tokenizer.tokenize(b)}search(b,d=10){if(!this.isLoaded||!b.trim())return[];const f=this.tokenize(b);if(0===f.length)return[];
const c={};f.forEach(a=>{c[a]=(c[a]||0)+1});const g={};let h=0;Object.keys(c).forEach(a=>{if(Object.prototype.hasOwnProperty.call(this.idf,a)){const e=c[a]/f.length*(this.idf[a]||1);g[a]=e;h+=e*e}});const n=0<h?Math.sqrt(h):1,l={};Object.keys(g).forEach(a=>{l[a]=g[a]/n});const k=[],m=b.toLowerCase();this.docs.forEach((a,e)=>{e=VectorScorer.calculateCosineSimilarity(l,this.vectors[e]||{});const p=a.name.toLowerCase(),q=a.summary.toLowerCase();p.includes(m)?e+=2:q.includes(m)&&(e+=.5);.05<e&&k.push({doc:a,
score:e})});k.sort((a,e)=>e.score-a.score);return k.slice(0,d).map(a=>({...a.doc,score:a.score.toFixed(4)}))}}"undefined"!==typeof window&&(window.CustomSearchEngine=CustomSearchEngine);"undefined"!==typeof module&&module.exports&&(module.exports=CustomSearchEngine);
